// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title PriceOracle
 * @dev Aggregates price data from Chainlink oracles for forex pairs
 * Provides fallback mechanisms and staleness checks
 */
contract PriceOracle is Ownable {
    // Mapping: currency pair => Chainlink oracle address
    mapping(string => address) public priceFeeds;
    
    // Maximum allowed staleness for price data (in seconds)
    uint256 public maxStaleness = 3600; // 1 hour
    
    // Minimum confidence threshold (can be used for additional validation)
    uint256 public minConfidence = 95; // 95%
    
    event PriceFeedUpdated(string indexed pair, address feedAddress);
    event PriceRequested(string indexed pair, int256 price, uint256 timestamp);
    event MaxStalenessUpdated(uint256 oldValue, uint256 newValue);
    
    struct PriceData {
        int256 price;
        uint256 timestamp;
        uint80 roundId;
        bool isValid;
    }

    /**
     * @dev Updated for OpenZeppelin v5: pass initialOwner to Ownable
     */
    constructor() Ownable(msg.sender) {}

    /**
     * @dev Set Chainlink price feed for a currency pair
     * @param pair Currency pair (e.g., "EUR/USD")
     * @param feedAddress Chainlink aggregator address
     */
    function setPriceFeed(string memory pair, address feedAddress) 
        external 
        onlyOwner 
    {
        require(feedAddress != address(0), "Invalid feed address");
        priceFeeds[pair] = feedAddress;
        emit PriceFeedUpdated(pair, feedAddress);
    }
    
    /**
     * @dev Update maximum allowed staleness
     * @param newMaxStaleness New staleness threshold in seconds
     */
    function setMaxStaleness(uint256 newMaxStaleness) 
        external 
        onlyOwner 
    {
        require(newMaxStaleness > 0, "Staleness must be greater than 0");
        uint256 oldValue = maxStaleness;
        maxStaleness = newMaxStaleness;
        emit MaxStalenessUpdated(oldValue, newMaxStaleness);
    }
    
    /**
     * @dev Get latest price for a currency pair
     * @param pair Currency pair (e.g., "EUR/USD")
     * @return PriceData struct with price and metadata
     */
    function getLatestPrice(string memory pair) 
        public 
        view 
        returns (PriceData memory) 
    {
        address feedAddress = priceFeeds[pair];
        require(feedAddress != address(0), "Price feed not set for this pair");
        
        AggregatorV3Interface priceFeed = AggregatorV3Interface(feedAddress);
        
        try priceFeed.latestRoundData() returns (
            uint80 roundId,
            int256 price,
            uint256 /* startedAt */,
            uint256 updatedAt,
            uint80 /* answeredInRound */
        ) {
            // Check if price data is stale
            bool isValid = (block.timestamp - updatedAt) <= maxStaleness;
            
            return PriceData({
                price: price,
                timestamp: updatedAt,
                roundId: roundId,
                isValid: isValid
            });
        } catch {
            // Return invalid price data if oracle call fails
            return PriceData({
                price: 0,
                timestamp: 0,
                roundId: 0,
                isValid: false
            });
        }
    }
    
    /**
     * @dev Get latest valid price or revert
     * @param pair Currency pair
     * @return price Latest price (scaled by oracle decimals)
     */
    function getLatestValidPrice(string memory pair) 
        external 
        view 
        returns (int256 price) 
    {
        PriceData memory priceData = getLatestPrice(pair);
        require(priceData.isValid, "Price data is stale or invalid");
        require(priceData.price > 0, "Invalid price");
        
        return priceData.price;
    }
    
    /**
     * @dev Get decimals for a price feed
     * @param pair Currency pair
     * @return decimals Number of decimals
     */
    function getDecimals(string memory pair) 
        external 
        view 
        returns (uint8) 
    {
        address feedAddress = priceFeeds[pair];
        require(feedAddress != address(0), "Price feed not set");
        
        AggregatorV3Interface priceFeed = AggregatorV3Interface(feedAddress);
        return priceFeed.decimals();
    }
    
    /**
     * @dev Check if price feed exists for a pair
     * @param pair Currency pair
     * @return bool True if feed exists
     */
    function hasPriceFeed(string memory pair) 
        external 
        view 
        returns (bool) 
    {
        return priceFeeds[pair] != address(0);
    }
    
    /**
     * @dev Calculate exchange rate between two currencies
     * @param baseCurrency Base currency (e.g., "USD")
     * @param quoteCurrency Quote currency (e.g., "EUR")
     * @return rate Exchange rate (scaled)
     */
    function getExchangeRate(string memory baseCurrency, string memory quoteCurrency) 
        external 
        view 
        returns (int256 rate) 
    {
        // First try direct pair
        string memory directPair = string(abi.encodePacked(baseCurrency, "/", quoteCurrency));
        if (priceFeeds[directPair] != address(0)) {
            PriceData memory priceData = getLatestPrice(directPair);
            require(priceData.isValid, "Price data is stale");
            return priceData.price;
        }
        
        // Try inverse pair
        string memory inversePair = string(abi.encodePacked(quoteCurrency, "/", baseCurrency));
        if (priceFeeds[inversePair] != address(0)) {
            PriceData memory priceData = getLatestPrice(inversePair);
            require(priceData.isValid, "Price data is stale");
            require(priceData.price > 0, "Invalid price");
            
            // Calculate inverse (1 / price) with proper scaling
            return int256(10**16) / priceData.price; // Assuming 8 decimals
        }
        
        revert("No price feed available for this pair");
    }
}

src/contracts/PriceOracleV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@chainlink/contracts/src/v0.8/shared/interfaces/AggregatorV3Interface.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title PriceOracleV2
 * @notice Price oracle using bytes32 pair IDs for TradingPlatformV2 compatibility
 * @dev Uses Chainlink price feeds with keccak256 hashed pair identifiers
 */
contract PriceOracleV2 is Ownable {
    
    // Mapping from bytes32 pairId to Chainlink price feed address
    mapping(bytes32 => address) public priceFeeds;
    
    // Events
    event PriceFeedSet(bytes32 indexed pairId, address feedAddress);
    event PriceFeedRemoved(bytes32 indexed pairId);

    constructor() Ownable(msg.sender) {}

    /**
     * @notice Set a price feed for a trading pair
     * @param pairId The keccak256 hash of the pair string (e.g., keccak256("EUR/USD"))
     * @param feedAddress The Chainlink aggregator address
     */
    function setPriceFeed(bytes32 pairId, address feedAddress) external onlyOwner {
        require(feedAddress != address(0), "Invalid feed address");
        priceFeeds[pairId] = feedAddress;
        emit PriceFeedSet(pairId, feedAddress);
    }

    /**
     * @notice Set multiple price feeds at once
     * @param pairIds Array of pair IDs
     * @param feedAddresses Array of corresponding feed addresses
     */
    function setPriceFeeds(bytes32[] calldata pairIds, address[] calldata feedAddresses) external onlyOwner {
        require(pairIds.length == feedAddresses.length, "Length mismatch");
        
        for (uint256 i = 0; i < pairIds.length; i++) {
            require(feedAddresses[i] != address(0), "Invalid feed address");
            priceFeeds[pairIds[i]] = feedAddresses[i];
            emit PriceFeedSet(pairIds[i], feedAddresses[i]);
        }
    }

    /**
     * @notice Remove a price feed
     * @param pairId The pair ID to remove
     */
    function removePriceFeed(bytes32 pairId) external onlyOwner {
        delete priceFeeds[pairId];
        emit PriceFeedRemoved(pairId);
    }

    /**
     * @notice Get the current price for a trading pair
     * @param pairId The keccak256 hash of the pair string
     * @return price The current price (8 decimals for most forex pairs)
     * @return updatedAt The timestamp of the last price update
     */
    function getPrice(bytes32 pairId) external view returns (uint256 price, uint256 updatedAt) {
        address feed = priceFeeds[pairId];
        require(feed != address(0), "Feed not set");

        AggregatorV3Interface priceFeed = AggregatorV3Interface(feed);
        
        (
            /* uint80 roundId */,
            int256 answer,
            /* uint256 startedAt */,
            uint256 timestamp,
            /* uint80 answeredInRound */
        ) = priceFeed.latestRoundData();

        require(answer > 0, "Invalid price");
        
        return (uint256(answer), timestamp);
    }

    /**
     * @notice Get detailed price data for a trading pair
     * @param pairId The pair ID
     * @return roundId The round ID from Chainlink
     * @return price The current price
     * @return startedAt When the round started
     * @return updatedAt When the price was last updated
     * @return answeredInRound The round in which the answer was computed
     */
    function getPriceData(bytes32 pairId) external view returns (
        uint80 roundId,
        int256 price,
        uint256 startedAt,
        uint256 updatedAt,
        uint80 answeredInRound
    ) {
        address feed = priceFeeds[pairId];
        require(feed != address(0), "Feed not set");

        AggregatorV3Interface priceFeed = AggregatorV3Interface(feed);
        return priceFeed.latestRoundData();
    }

    /**
     * @notice Get the decimals for a price feed
     * @param pairId The pair ID
     * @return The number of decimals
     */
    function getDecimals(bytes32 pairId) external view returns (uint8) {
        address feed = priceFeeds[pairId];
        require(feed != address(0), "Feed not set");
        
        return AggregatorV3Interface(feed).decimals();
    }

    /**
     * @notice Check if a price feed is configured
     * @param pairId The pair ID to check
     * @return True if the feed is set
     */
    function hasFeed(bytes32 pairId) external view returns (bool) {
        return priceFeeds[pairId] != address(0);
    }

    /**
     * @notice Helper to compute pair ID from string
     * @param pair The pair string (e.g., "EUR/USD")
     * @return The keccak256 hash
     */
    function computePairId(string calldata pair) external pure returns (bytes32) {
        return keccak256(abi.encodePacked(pair));
    }
}

